"""Compose the session report from frozen experiment records. Publish only with all results."""
from pathlib import Path
import json
import re
import sys
from docx.shared import Pt
import layout as w

D = Path(__file__).resolve().parent
R = D.parent
O = R.parents[1]/"outputs"
def j(name):
    return json.loads((R/name).read_text(encoding="utf-8-sig"))
def count(n):
    return f"{n:,}".replace(","," ")
def fmt(v,n=2):
    return f"{v:.{n}f}".replace(".",",").replace("-","−")
def links(*items):
    p=w.doc.add_paragraph(style="Ref")
    for i,(label,url) in enumerate(items):
        if i: p.add_run("   ·   ")
        w.link(p,url,label)
def table(cols,rows,widths):
    w.tbl(cols,rows,widths,small=False)
def intro():
    w.doc.core_properties.title="Что сохранять в рабочей памяти агента"
    w.doc.core_properties.subject="Эксперименты с памятью во время решения задачи"
    w.p("ИССЛЕДОВАТЕЛЬСКИЙ ОТЧЁТ     /     17 НОЯБРЯ 2026","Section line")
